import { tool, generateText, stepCountIs } from 'ai';
import { z } from 'zod';
import { findOrder } from './src/data/orders.js';
import { scriptedModel } from './test/helpers/mock-model.js';

const testTool = tool({
  description: 'Get the status of an order',
  parameters: z.object({
    orderId: z.string().describe('The order ID to look up'),
  }),
  execute: async ({ orderId }, { customerId }) => {
    const order = findOrder(orderId);
    if (!order || order.customerId !== customerId) {
      return { orderId, error: 'not found' };
    }
    return { orderId, status: order.status, eta: order.eta };
  },
});

const model = scriptedModel([
  { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }] },
  { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A101' } }] },
  { text: 'Your orders are: order A100 is shipped and order A101 is processing.' },
]);

const result = await generateText({
  model,
  tools: { getOrderStatus: testTool },
  toolsContext: { customerId: 'C1' },
  prompt: 'Tell me about my orders',
  system: 'You are Acme\\'s order-status assistant. Answer in one short sentence.',
  stopWhen: stepCountIs(5),
});

console.log('Tool calls:');
result.toolCalls.forEach((tc, i) => {
  console.log(i, ':', JSON.stringify(tc));
});

console.log('\\nLookedUp order ids:');
const lookedUp = result.toolCalls.map(tc => tc.input.orderId);
console.log(lookedUp);
"

